import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.ticker as mtick
import io
import base64
import numpy as np

# Set matplotlib style
plt.style.use('bmh')

# Load Data
df = pd.read_csv('/app/benchmark/data.csv')

# Preprocessing
df_all = df[(df['sex'] == 'both') & (df['age_group'] == 'ALL')].copy()

# Calculate KPIs
idx_recent = df_all.groupby('country')['year'].idxmax()
df_recent = df_all.loc[idx_recent]

kpi_median_rate = df_recent['homicide_rate'].median()

# Male-to-Female Ratio
df_sex = df[(df['sex'].isin(['male', 'female'])) & (df['age_group'] == 'ALL')]
df_sex_recent = df_sex.loc[df_sex.groupby(['country', 'sex'])['year'].idxmax()]
male_mean = df_sex_recent[df_sex_recent['sex'] == 'male']['homicide_rate'].mean()
female_mean = df_sex_recent[df_sex_recent['sex'] == 'female']['homicide_rate'].mean()
kpi_mf_ratio = male_mean / female_mean if female_mean else 0

# Highest National Rate
highest_country_row = df_recent.loc[df_recent['homicide_rate'].idxmax()]
kpi_highest_rate = highest_country_row['homicide_rate']
kpi_highest_country = highest_country_row['country']

# Decade-over-Decade Change
df_all['decade'] = (df_all['year'] // 10) * 10
decade_means = df_all.groupby('decade')['homicide_rate'].mean()
if 2010 in decade_means and 2020 in decade_means:
    kpi_dec_change = (decade_means[2020] - decade_means[2010]) / decade_means[2010]
else:
    kpi_dec_change = 0

# Reporting Coverage Rate
total_countries = df['iso_code'].nunique()
avg_reporting = df_all.groupby('year')['iso_code'].nunique().mean()
kpi_coverage = avg_reporting / total_countries

# Helper function for charts
def get_base64_image(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Chart 1: Global Trend
fig1, ax1 = plt.subplots(figsize=(10, 5))
yearly_stats = df_all.groupby('year')['homicide_rate'].agg(['mean', 'median'])
ax1.plot(yearly_stats.index, yearly_stats['mean'], label='Global Mean', color='#e74c3c', linewidth=2.5)
ax1.plot(yearly_stats.index, yearly_stats['median'], label='Global Median', color='#2980b9', linewidth=2.5)
ax1.set_title('Global Homicide Rate Trend (1990-2023)', fontsize=14, pad=15)
ax1.set_ylabel('Homicides per 100,000')
ax1.grid(True, alpha=0.3)
ax1.legend()
img_trend = get_base64_image(fig1)

# Chart 2: Top & Bottom Countries
fig2, (ax2a, ax2b) = plt.subplots(1, 2, figsize=(14, 6))
top10 = df_recent.nlargest(10, 'homicide_rate').sort_values('homicide_rate', ascending=True)
bottom10 = df_recent[df_recent['homicide_rate'] > 0].nsmallest(10, 'homicide_rate').sort_values('homicide_rate', ascending=True)

ax2a.barh(top10['country'], top10['homicide_rate'], color='#c0392b')
ax2a.set_title('Top 10 Highest Rates (Most Recent Year)', fontsize=12)
ax2a.set_xlabel('Homicides per 100,000')

ax2b.barh(bottom10['country'], bottom10['homicide_rate'], color='#27ae60')
ax2b.set_title('Top 10 Lowest Rates (Most Recent Year, >0)', fontsize=12)
ax2b.set_xlabel('Homicides per 100,000')
plt.tight_layout()
img_top_bottom = get_base64_image(fig2)

# Chart 3: Gender Disparity
fig3, ax3 = plt.subplots(figsize=(10, 5))
sex_yearly = df_sex.groupby(['year', 'sex'])['homicide_rate'].mean().unstack()
if 'male' in sex_yearly.columns and 'female' in sex_yearly.columns:
    ax3.plot(sex_yearly.index, sex_yearly['male'], label='Male Mean', color='#2c3e50', linewidth=2.5)
    ax3.plot(sex_yearly.index, sex_yearly['female'], label='Female Mean', color='#e67e22', linewidth=2.5)
ax3.set_title('Global Mean Homicide Rate by Sex (1990-2023)', fontsize=14, pad=15)
ax3.set_ylabel('Homicides per 100,000')
ax3.grid(True, alpha=0.3)
ax3.legend()
img_sex = get_base64_image(fig3)

# Chart 4: Age Group Analysis
df_age = df[(df['age_group'] != 'ALL') & (df['sex'] == 'both')]
age_counts = df_age['age_group'].value_counts()
valid_age_groups = age_counts[age_counts > 50].index # Filter out very rare custom age brackets
age_means = df_age[df_age['age_group'].isin(valid_age_groups)].groupby('age_group')['homicide_rate'].mean().sort_values(ascending=False).head(12)

fig4, ax4 = plt.subplots(figsize=(10, 5))
age_means.plot(kind='bar', ax=ax4, color='#8e44ad')
ax4.set_title('Average Homicide Rate by Age Group (Common Brackets)', fontsize=14, pad=15)
ax4.set_ylabel('Homicides per 100,000')
plt.xticks(rotation=45, ha='right')
plt.tight_layout()
img_age = get_base64_image(fig4)

# Chart 5: Reporting Coverage
fig5, ax5 = plt.subplots(figsize=(10, 4))
coverage_yearly = df_all.groupby('year')['iso_code'].nunique()
ax5.bar(coverage_yearly.index, coverage_yearly.values, color='#95a5a6')
ax5.set_title('Number of Reporting Countries per Year (Coverage)', fontsize=14, pad=15)
ax5.set_ylabel('Countries Reporting')
ax5.grid(True, alpha=0.3, axis='y')
img_coverage = get_base64_image(fig5)

# Calculate Notable Trends
# Compare mean of first 3 available years vs last 3 available years per country
trend_data = []
for country, group in df_all.groupby('country'):
    if len(group) >= 10: # Need at least 10 years of data to compute a meaningful long-term trend
        group = group.sort_values('year')
        early_mean = group.head(3)['homicide_rate'].mean()
        late_mean = group.tail(3)['homicide_rate'].mean()
        if early_mean > 0:
            pct_change = (late_mean - early_mean) / early_mean
            trend_data.append({'country': country, 'early': early_mean, 'late': late_mean, 'change': pct_change})

trend_df = pd.DataFrame(trend_data)
if not trend_df.empty:
    biggest_increases = trend_df.nlargest(5, 'change')
    biggest_decreases = trend_df.nsmallest(5, 'change')
else:
    biggest_increases = pd.DataFrame()
    biggest_decreases = pd.DataFrame()


